import { Link } from 'react-router-dom'
import { Card } from '@/components/ui'
import { Icon, type IconName } from '@/design-system/Icon'
import { useI18n, type MessageKey } from '@/i18n'
import { useSession } from '@/app/session'
import { STAGE_LABEL } from '@/app/nav'
import PairPanel from '@/features/sync/PairPanel'

/**
 * Who you two are, and everything that belongs to the pair rather than to a day.
 *
 * Before this screen, the answers to "who is using this", "how do I connect my
 * partner's phone", "where is my backup" and "where are the rest of the
 * features" lived on four different screens, two of which were only reachable
 * from a directory. None of them is a daily task, and all of them are the kind
 * of thing you go looking for on purpose — which is exactly what a tab is for.
 *
 * Pairing is at the top rather than buried in settings, because connecting two
 * phones is the single thing this app is named after and the one people were
 * most reliably failing to find.
 */

interface Dest {
  to: string
  label: MessageKey
  desc: MessageKey
  icon: IconName
}

const DESTINATIONS: Dest[] = [
  { to: '/temu', label: 'temu.title', desc: 'mod.temuDesc', icon: 'temu' },
  { to: '/semua', label: 'nav.all', desc: 'mod.allHint', icon: 'shared' },
  { to: '/privasi', label: 'priv.title', desc: 'mod.privacyDesc', icon: 'shield' },
  { to: '/pengaturan', label: 'set.title', desc: 'us.settingsDesc', icon: 'settings' },
  { to: '/bantuan', label: 'help.title', desc: 'us.helpDesc', icon: 'info' },
]

export default function Kami() {
  const { t } = useI18n()
  const { profile, partner } = useSession()

  const names = [profile?.displayName, partner?.displayName].filter(Boolean).join(' & ')

  return (
    <div className="stack">
      <h1>{t('nav.us2')}</h1>

      <Card icon="heart" title={names || t('us.whoTitle')} hint={profile ? t(STAGE_LABEL[profile.stage]) : undefined}>
        <p className="card__hint">{t('us.whoHint')}</p>
        <Link className="btn btn--soft btn--sm" to="/pengaturan">
          <Icon name="settings" size={18} />
          {t('us.editProfile')}
        </Link>
      </Card>

      <PairPanel />

      {/* Same tile as the directory uses, so the two screens do not invent two
          different ways to look like a list of places to go. */}
      <div className="modgrid">
        {DESTINATIONS.map((d) => (
          <Link key={d.to} to={d.to} className="modcard">
            <span className="modcard__ic">
              <Icon name={d.icon} size={22} />
            </span>
            <span className="modcard__body">
              <strong>{t(d.label)}</strong>
              <small>{t(d.desc)}</small>
            </span>
          </Link>
        ))}
      </div>
    </div>
  )
}
